using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        int i = 0;
        ref int start = ref MemoryMarshal.GetReference(data);

        // Compare > threshold produces all-ones (-1) for matches.
        // Subtracting -1 adds 1; subtracting 0 is a no-op.
        if (Vector512.IsHardwareAccelerated && data.Length >= Vector512<int>.Count)
        {
            var vThreshold = Vector512.Create(threshold);
            int limit = data.Length - Vector512<int>.Count;
            for (; i <= limit; i += Vector512<int>.Count)
            {
                ref int p = ref Unsafe.Add(ref start, i);
                var v = Vector512.LoadUnsafe(ref p);
                var mask = Vector512.GreaterThan(v, vThreshold);
                Vector512.StoreUnsafe(Vector512.Subtract(v, mask), ref p);
            }
        }
        else if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<int>.Count)
        {
            var vThreshold = Vector256.Create(threshold);
            int limit = data.Length - Vector256<int>.Count;
            for (; i <= limit; i += Vector256<int>.Count)
            {
                ref int p = ref Unsafe.Add(ref start, i);
                var v = Vector256.LoadUnsafe(ref p);
                var mask = Vector256.GreaterThan(v, vThreshold);
                Vector256.StoreUnsafe(Vector256.Subtract(v, mask), ref p);
            }
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<int>.Count)
        {
            var vThreshold = Vector128.Create(threshold);
            int limit = data.Length - Vector128<int>.Count;
            for (; i <= limit; i += Vector128<int>.Count)
            {
                ref int p = ref Unsafe.Add(ref start, i);
                var v = Vector128.LoadUnsafe(ref p);
                var mask = Vector128.GreaterThan(v, vThreshold);
                Vector128.StoreUnsafe(Vector128.Subtract(v, mask), ref p);
            }
        }

        // Scalar tail
        for (; i < data.Length; i++)
        {
            if (Unsafe.Add(ref start, i) > threshold)
                Unsafe.Add(ref start, i)++;
        }
    }
}

